-- Additive seminar support. No old seminar, account, consent or ledger is imported.
CREATE TABLE IF NOT EXISTS s14_meta(seminar_id TEXT PRIMARY KEY REFERENCES seminars(id),business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),online_url TEXT NOT NULL,segments TEXT NOT NULL,mode TEXT NOT NULL,lead_hours INTEGER NOT NULL,clock TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(business_id,seminar_id));
CREATE TABLE IF NOT EXISTS s14_consents(id INTEGER PRIMARY KEY,seminar_id TEXT NOT NULL REFERENCES s14_meta(seminar_id),username TEXT NOT NULL REFERENCES seminar_registrations(username),purpose TEXT NOT NULL,granted INTEGER NOT NULL,notice TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS s14_preferences(seminar_id TEXT NOT NULL REFERENCES s14_meta(seminar_id),username TEXT NOT NULL REFERENCES seminar_registrations(username),interests TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(seminar_id,username));
CREATE TABLE IF NOT EXISTS s14_engagement(seminar_id TEXT NOT NULL REFERENCES s14_meta(seminar_id),username TEXT NOT NULL REFERENCES seminar_registrations(username),mode TEXT NOT NULL,interview TEXT NOT NULL DEFAULT 'none',evidence TEXT NOT NULL DEFAULT '',interview_at TEXT,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(seminar_id,username,mode));
CREATE TABLE IF NOT EXISTS s14_drafts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,seminar_id TEXT NOT NULL,username TEXT NOT NULL REFERENCES seminar_registrations(username),kind TEXT NOT NULL,mode TEXT NOT NULL,body TEXT NOT NULL,body_digest TEXT NOT NULL,snapshot TEXT NOT NULL,due_at TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_at TEXT,approved_by TEXT,created_at TEXT NOT NULL,FOREIGN KEY(business_id,seminar_id) REFERENCES s14_meta(business_id,seminar_id),UNIQUE(seminar_id,username,kind,mode,snapshot,due_at));
CREATE UNIQUE INDEX IF NOT EXISTS s14_active_draft ON s14_drafts(seminar_id,username,kind,mode) WHERE status IN ('approval_pending','send_waiting_no_api','retry_wait');
CREATE TABLE IF NOT EXISTS s14_attempts(id TEXT PRIMARY KEY,draft_id TEXT NOT NULL REFERENCES s14_drafts(id),outcome TEXT NOT NULL,mode TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS s14_work(task_id TEXT PRIMARY KEY REFERENCES tasks(id),business_id TEXT NOT NULL,seminar_id TEXT NOT NULL,activity TEXT NOT NULL,artifact_id TEXT REFERENCES artifacts(id),result TEXT,approved_by TEXT,paused INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(business_id,seminar_id) REFERENCES s14_meta(business_id,seminar_id));
CREATE TABLE IF NOT EXISTS s14_attributions(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,seminar_id TEXT NOT NULL,kind TEXT NOT NULL,source_ref TEXT NOT NULL,evidence TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(business_id,seminar_id) REFERENCES s14_meta(business_id,seminar_id));
CREATE UNIQUE INDEX IF NOT EXISTS s14_one_financial_source ON s14_attributions(kind,source_ref) WHERE active=1;
CREATE TABLE IF NOT EXISTS s14_scheduler(business_id TEXT PRIMARY KEY REFERENCES portfolio_businesses(id),enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS s14_events(id INTEGER PRIMARY KEY,business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),seminar_id TEXT,actor TEXT NOT NULL,event TEXT NOT NULL,ref TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS s14_draft_history(id TEXT PRIMARY KEY,draft_id TEXT NOT NULL REFERENCES s14_drafts(id),body TEXT NOT NULL,body_digest TEXT NOT NULL,created_at TEXT NOT NULL);
